actor TTLCache<Key: Hashable & Sendable, Value: Sendable> {
    private struct Entry { let value: Value; let expires: ContinuousClock.Instant }
    private var storage: [Key: Entry] = [:]
    private var order: [Key] = []
    private let ttl: Duration, capacity: Int
    private let clock = ContinuousClock()

    init(ttl: Duration, capacity: Int) { self.ttl = ttl; self.capacity = capacity }

    func value(for key: Key) -> Value? {
        guard let e = storage[key] else { return nil }
        if e.expires <= clock.now { remove(key); return nil }
        return e.value
    }

    func set(_ value: Value, for key: Key) {
        if storage[key] == nil { order.append(key) }
        storage[key] = Entry(value: value, expires: clock.now.advanced(by: ttl))
        while storage.count > capacity, let oldest = order.first { remove(oldest) }
    }

    private func remove(_ key: Key) {
        storage[key] = nil
        order.removeAll { $0 == key }
    }
}
